mapper.select:
select u.u_uid as uUid, u.user_name as userName, u.email, u.role, u.status, up.nick_name as nickName, up.avatar, u.created_at as createdAt, u.updated_at as updatedAt from users u join user_profile up on u.u_uid = up.u_uid where 1 = 1
and (u.user_name like concat('%', #{name}, '%') or up.nick_name like concat('%', #{name}, '%'))
and u.email like concat('%', #{email}, '%')
and u.role = #{role}
and u.status = #{status}
